package com.bte.service;
import com.bte.entity.*;import com.bte.repository.*;import lombok.RequiredArgsConstructor;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.util.*;
@Service @RequiredArgsConstructor
public class TournamentStandingsService {
 private final MatchResultRepository results;private final RegistrationRepository registrations;
 public record Standing(int rank,Long captainUserId,String teamName,int roundsPlayed,long placementPoints,long kills,long totalPoints){}
 @Transactional(readOnly=true) public List<Standing> standings(Long id){return aggregate(results.findByTournamentIdOrderByMatchNumberAsc(id),registrations.findByTournamentId(id));}
 public static List<Standing> aggregate(List<MatchResult> matches,List<Registration> entries){var totals=new HashMap<Long,long[]>();var names=new HashMap<Long,String>();for(var result:matches)for(var row:result.getRankings()){Long owner=entries.stream().filter(r->Objects.equals(row.getPlayerUserId(),r.getOwnerUserId()) || Objects.equals(row.getPlayerUserId(),r.getGuestAccountId())).map(Registration::getOwnerUserId).findFirst().orElse(row.getPlayerUserId());var sum=totals.computeIfAbsent(owner,k->new long[4]);sum[0]++;sum[1]+=row.getPlacementPoints();sum[2]+=row.getKills();sum[3]=row.getRank();names.put(owner,entries.stream().filter(r->Objects.equals(r.getOwnerUserId(),owner)).map(r->Objects.requireNonNullElse(r.getTeamName(),"Team #"+owner)).findFirst().orElse(Objects.requireNonNullElse(row.getTeamName(),"Team #"+owner)));}var ids=new ArrayList<>(totals.keySet());ids.sort(Comparator.<Long>comparingLong(k->totals.get(k)[1]+totals.get(k)[2]).reversed().thenComparing(Comparator.<Long>comparingLong(k->totals.get(k)[2]).reversed()).thenComparing(Comparator.<Long>comparingLong(k->totals.get(k)[1]).reversed()).thenComparingLong(k->totals.get(k)[3]).thenComparingLong(k->k));var output=new ArrayList<Standing>();int rank=1;for(var id:ids){var s=totals.get(id);output.add(new Standing(rank++,id,names.get(id),(int)s[0],s[1],s[2],s[1]+s[2]));}return output;}
}
